import os

工作台 = "小工作台"
os.makedirs(os.path.join(工作台, "里屋"), exist_ok=True)
for _ in range(3):
    名字 = input()
    with open(os.path.join(工作台, 名字), "w", encoding="utf-8") as 档案:
        档案.write("x")

for 名字 in sorted(os.listdir(工作台)):
    if os.path.isfile(os.path.join(工作台, 名字)):
        print(f"东西：{名字}")
    else:
        print(f"抽屉：{名字}")

